#!/usr/bin/env bash
# gen-skills-agents-audit.sh — TURNKEY: generates the skills/agents linter, verifies it, then runs it.
#
# Self-contained: the linter is embedded as base64 and written out at runtime, so this single file
# is all you need. No dependency on any previously-created script.
#
# Usage:
#   ./gen-skills-agents-audit.sh                       # generate + run audit on . (archives excluded)
#   ./gen-skills-agents-audit.sh <ROOT> [linter-args]  # forward args to the linter (e.g. --sync)
#   GEN_DEST=/path/check-skills-agents.sh ./gen-skills-agents-audit.sh   # keep the generated file
#   GEN_ONLY=1 ./gen-skills-agents-audit.sh            # generate only, do not run
#
# Exit: passes through the linter's exit code; 3 = checksum mismatch.
set -euo pipefail

ARGS=( "$@" )
DEST="${GEN_DEST:-$(mktemp -d)/check-skills-agents.sh}"
mkdir -p "$(dirname "$DEST")"

base64 -d > "$DEST" <<'PAYLOAD'

PAYLOAD
EXPECT_SHA="979719a7a60b74bdc2f04985a9db5b28a19450ea7f0c09ac8920b3fe9b874b37"
chmod +x "$DEST"

if command -v sha256sum >/dev/null 2>&1; then
  GOT="$(sha256sum "$DEST" | cut -d' ' -f1)"
  if [ "$GOT" != "$EXPECT_SHA" ]; then
    echo "❌ checksum mismatch: generated linter is corrupt (got $GOT, expected $EXPECT_SHA)" >&2
    exit 3
  fi
fi
echo "✅ generated linter: $DEST"

if [ "${GEN_ONLY:-0}" = "1" ]; then exit 0; fi

if [ ${#ARGS[@]} -eq 0 ]; then ARGS=( . --exclude '*_archived*' ); fi
echo "▶ running: $DEST ${ARGS[*]}"
echo
exec bash "$DEST" "${ARGS[@]}"
